BASE_WAIT_MS = 100

def run_request(outcomes, providers, max_retries):
    pos = 0                    # next unused outcome
    attempts = 0
    wait_ms = 0
    for provider in providers:
        # one first try + up to max_retries retries on this provider
        for retry in range(max_retries + 1):
            if retry > 0:
                wait_ms += BASE_WAIT_MS * 2 ** (retry - 1)   # backoff before a retry
            outcome = outcomes[pos] if pos < len(outcomes) else 'ok'
            pos += 1
            attempts += 1
            if outcome == 'ok':
                return [provider, attempts, wait_ms]
        # this provider is exhausted: switch with no wait, backoff starts over
    return ['FAILED', attempts, wait_ms]

def solution(requests, providers, max_retries):
    return [run_request(outcomes, providers, max_retries) for outcomes in requests]
